<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin' })
const route = useRoute(); const API_URL = 'http://localhost:8000'; const form = reactive({ name: '', slug: '' }); const loading = ref(true); const saving = ref(false); const errorMessage = ref('')
onMounted(async () => { try { Object.assign(form, await $fetch<any>(`${API_URL}/categories/${route.params.id}`)) } catch { errorMessage.value = 'Category not found.' } finally { loading.value = false } })
const save = async () => { saving.value = true; try { await $fetch(`${API_URL}/categories/${route.params.id}`, { method: 'PUT', body: form }); await navigateTo('/admin/categories') } catch { errorMessage.value = 'Unable to save category.' } finally { saving.value = false } }
</script>
<template><section><AdminHeader title="Edit category" description="Update category information." /><div v-if="loading" class="py-20 text-center text-sm text-gray-500">Loading...</div><form v-else class="max-w-xl space-y-5 rounded-2xl border border-[#d9e7e2] bg-white p-6 shadow-sm" @submit.prevent="save"><p v-if="errorMessage" class="rounded-xl bg-red-50 p-4 text-sm text-red-700">{{ errorMessage }}</p><label class="block"><span class="field-label">Name</span><input v-model="form.name" required class="field-input" /></label><label class="block"><span class="field-label">Slug</span><input v-model="form.slug" required class="field-input" /></label><div class="flex justify-end gap-3"><NuxtLink to="/admin/categories" class="rounded-xl border border-gray-200 px-5 py-3 text-sm font-semibold text-gray-600">Cancel</NuxtLink><button :disabled="saving" class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">{{ saving ? 'Saving...' : 'Save changes' }}</button></div></form></section></template>
<style scoped>.field-label{display:block;margin-bottom:.5rem;font-size:.75rem;font-weight:700;color:#536461}.field-input{width:100%;border:1px solid #d7e1dd;border-radius:.75rem;padding:.75rem 1rem;outline:none}.field-input:focus{border-color:#0f766e;box-shadow:0 0 0 4px rgba(15,118,110,.1)}</style>
